    private static int adapt(MethodNode method,boolean reverse){int count=0;String attribute="Lnet/minecraft/world/entity/ai/attributes/Attribute;",effect="Lnet/minecraft/world/effect/MobEffect;",holder="Lnet/minecraft/core/Holder;";for(AbstractInsnNode instruction:method.instructions){if(instruction instanceof FieldInsnNode field&&(field.owner.equals("net/minecraft/world/entity/ai/attributes/Attributes")||field.owner.equals("net/minecraft/world/effect/MobEffects"))){String old=field.owner.endsWith("Attributes")?attribute:effect;String from=reverse?holder:old,to=reverse?old:holder;require(field.desc.equals(from),"Exact original Holder field adapter "+field.name);field.desc=to;count++;}if(instruction instanceof MethodInsnNode call){String old=null;if(call.name.equals("getAttribute")||call.name.equals("getAttributeValue"))old=attribute;if(call.owner.equals("net/minecraft/world/effect/MobEffectInstance")&&call.name.equals("<init>"))old=effect;if(old!=null){String from=reverse?holder:old,to=reverse?old:holder;require(call.desc.contains(from),"Exact original Holder argument adapter "+call.name);call.desc=call.desc.replace(from,to);count++;}}}return count;}
