    private static List<AbstractInsnNode> code(MethodNode method){return Arrays.stream(method.instructions.toArray()).filter(value->value.getOpcode()>=0).toList();}
    private static JsonObject row(ClassNode node,MethodNode method,String originalGraph,String category){JsonObject value=new JsonObject();value.addProperty("owner",node.name);value.addProperty("method",method.name);value.addProperty("descriptor",method.desc);value.addProperty("mappedOriginalGraph",originalGraph);value.addProperty("portedGraph",graph(method));value.addProperty("adapter",category);return value;}
    private static void damageAdapter(ClassNode node,MethodNode method){List<AbstractInsnNode> instructions=code(method);require(instructions.get(0) instanceof VarInsnNode variable&&variable.getOpcode()==Opcodes.ALOAD&&variable.var==0,"Exact original damage cancellation receiver");require(instructions.get(1) instanceof MethodInsnNode call&&call.owner.equals("net/neoforged/neoforge/event/entity/living/LivingDamageEvent$Pre")&&call.name.equals("isCanceled")&&call.desc.equals("()Z"),"Exact original cancellation method");require(instructions.get(2).getOpcode()==Opcodes.IFNE,"Original canceled return branch");method.instructions.set(instructions.get(0),new InsnNode(Opcodes.ICONST_0));method.instructions.remove(instructions.get(1));int amounts=0;for(AbstractInsnNode instruction:method.instructions)if(instruction instanceof MethodInsnNode call&&call.owner.equals("net/neoforged/neoforge/event/entity/living/LivingDamageEvent$Pre")&&call.name.equals("getAmount")){require(call.desc.equals("()F"),"Exact original final damage amount");call.name="getNewDamage";amounts++;}require(amounts==1,"One original amount read adapted to uncancelable native Pre");}
    private static void tickAdapter(MethodNode method){List<AbstractInsnNode> instructions=code(method);int index=-1;for(int cursor=0;cursor<instructions.size();cursor++)if(instructions.get(cursor) instanceof FieldInsnNode field&&field.name.equals("phase")){require(index<0,"Unique original tick phase gate");index=cursor;}require(index>=1,"Original tick phase gate exists");require(instructions.get(index-1) instanceof VarInsnNode variable&&variable.var==0&&variable.getOpcode()==Opcodes.ALOAD,"Exact old tick receiver");require(instructions.get(index+1) instanceof FieldInsnNode field&&field.name.equals("END")&&field.getOpcode()==Opcodes.GETSTATIC,"Exact END phase constant");require(instructions.get(index+2).getOpcode()==Opcodes.IF_ACMPNE,"Exact old phase branch");for(int cursor=index-1;cursor<=index+2;cursor++)method.instructions.remove(instructions.get(cursor));}
    private static void savedGetAdapter(MethodNode method){int count=0;for(AbstractInsnNode instruction:method.instructions)if(instruction instanceof MethodInsnNode call&&call.owner.equals("net/minecraft/world/level/storage/DimensionDataStorage")&&call.name.equals("computeIfAbsent")){require(call.getOpcode()==Opcodes.INVOKEVIRTUAL&&call.desc.equals("(Ljava/util/function/Function;Ljava/util/function/Supplier;Ljava/lang/String;)Lnet/minecraft/world/level/saveddata/SavedData;"),"Exact old function/supplier saved-data access");call.setOpcode(Opcodes.INVOKESTATIC);call.owner=BRIDGE;call.desc="(Lnet/minecraft/world/level/storage/DimensionDataStorage;Ljava/util/function/Function;Ljava/util/function/Supplier;Ljava/lang/String;)Lnet/minecraft/world/level/saveddata/SavedData;";count++;}require(count==1,"One storage factory API bridge");}
    private static void reverseCheck(MethodNode original,MethodNode changed,String category){MethodNode reversed=copy(changed);if(category.equals("native-pre")){List<AbstractInsnNode> instructions=code(reversed);require(instructions.getFirst().getOpcode()==Opcodes.ICONST_0,"Reverse cancellation anchor");InsnList replacement=new InsnList();replacement.add(new VarInsnNode(Opcodes.ALOAD,0));replacement.add(new MethodInsnNode(Opcodes.INVOKEVIRTUAL,"net/neoforged/neoforge/event/entity/living/LivingDamageEvent$Pre","isCanceled","()Z",false));reversed.instructions.insertBefore(instructions.getFirst(),replacement);reversed.instructions.remove(instructions.getFirst());for(AbstractInsnNode instruction:reversed.instructions)if(instruction instanceof MethodInsnNode call&&call.owner.equals("net/neoforged/neoforge/event/entity/living/LivingDamageEvent$Pre")&&call.name.equals("getNewDamage"))call.name="getAmount";}else if(category.equals("native-post")){List<AbstractInsnNode> old=code(original),instructions=code(reversed);int index=-1;for(int cursor=0;cursor<old.size();cursor++)if(old.get(cursor) instanceof FieldInsnNode field&&field.name.equals("phase"))index=cursor;require(index==3,"Exact original server lookup precedes phase gate");InsnList replacement=new InsnList();Map<LabelNode,LabelNode> labels=new HashMap<>();for(AbstractInsnNode instruction:original.instructions)if(instruction instanceof LabelNode label)labels.put(label,new LabelNode());for(int cursor=index-1;cursor<=index+2;cursor++){AbstractInsnNode instruction=old.get(cursor);if(instruction instanceof JumpInsnNode jump){AbstractInsnNode target=jump.label;while(target!=null&&target.getOpcode()<0)target=target.getNext();int ordinal=old.indexOf(target);AbstractInsnNode reverseTarget=instructions.get(ordinal-4);LabelNode label=new LabelNode();reversed.instructions.insertBefore(reverseTarget,label);replacement.add(new JumpInsnNode(jump.getOpcode(),label));}else replacement.add(instruction.clone(labels));}reversed.instructions.insertBefore(instructions.get(index-1),replacement);}else if(category.equals("saved-factory")){for(AbstractInsnNode instruction:reversed.instructions)if(instruction instanceof MethodInsnNode call&&call.owner.equals(BRIDGE)&&call.name.equals("computeIfAbsent")){call.setOpcode(Opcodes.INVOKEVIRTUAL);call.owner="net/minecraft/world/level/storage/DimensionDataStorage";call.desc="(Ljava/util/function/Function;Ljava/util/function/Supplier;Ljava/lang/String;)Lnet/minecraft/world/level/saveddata/SavedData;";}}else if(category.equals("saved-provider")){reversed.desc=original.desc;reversed.signature=original.signature;}require(graph(original).equals(graph(reversed)),"Exact reverse adapter restores whole mapped original method "+changed.name+category);}
