        JsonObject proof=new JsonObject();proof.addProperty("checks",checks);proof.addProperty("linkageReferences",linkageChecks);proof.addProperty("restoredWholeSupportMethods",5);proof.addProperty("originalHelpersAdded",4);proof.addProperty("nativeStorageAdaptersAdded",1);proof.addProperty("negativeControls",2);proof.addProperty("wholeOriginalMethodsReverseProven",4);proof.addProperty("unchangedSupportLifecycleMethods",true);proof.add("restoredSupportMethods",restored);proof.add("helperMethods",helpers);proof.addProperty("nativeRuntimeAccepted",false);proof.addProperty("actualMultiplayerGameplayAccepted",false);proof.addProperty("installable",false);Files.writeString(out.resolve("composition-proof.json"),new GsonBuilder().setPrettyPrinting().create().toJson(proof));System.out.println("checks="+checks+";linkageReferences="+linkageChecks+";restoredWholeSupportMethods=5;originalHelpersAdded=4;nativeStorageAdapters=1;reverseAdapterProofs=4;negativeControls=2;");
